contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 dummy) public payable {
        require(dummy == dummy);

        bool reverted;
        bool pausedValue;
        try c.paused() returns (bool v) {
            reverted = false;
            pausedValue = v;
        } catch {
            reverted = true;
        }

        assert(!reverted);
        assert(pausedValue == true || pausedValue == false);
    }

    receive() external payable {}
}

