contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool doPause) public payable {
        bool wasPaused = c.paused();

        bool callSucceeded;
        if (doPause) {
            try c.pause() {
                callSucceeded = true;
            } catch {
                callSucceeded = false;
            }
        }

        bool isPaused = c.paused();

        if (!doPause) {
            assert(isPaused == wasPaused);
        } else {
            assert(isPaused == (wasPaused || callSucceeded));
        }
    }

    receive() external payable {}
}

