contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newLrtConfig) public payable {
        // Precondition: the test contract does not hold DEFAULT_ADMIN_ROLE in c's current lrtConfig.
        // IAccessControl has hasRole; call through the interface already present in the compilation unit.
        address current = address(c.lrtConfig());
        bool callerIsAdmin = IAccessControl(current).hasRole(bytes32(0), address(this));
        require(!callerIsAdmin, "precondition: caller must not be admin");

        // Read before-state.
        address before = address(c.lrtConfig());

        // Top-level deciding call (mutating).
        bool reverted;
        try c.updateLRTConfig(newLrtConfig) { reverted = false; } catch { reverted = true; }

        // Read after-state via public getter.
        address after_ = address(c.lrtConfig());

        // General rule: a non-admin caller can never change lrtConfig, so the call reverts
        // and the stored address stays exactly the same, regardless of the new address value.
        assert(reverted && after_ == before);
    }

    receive() external payable {}
}

