contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address admin) public payable {
        require(admin != address(0), "admin zero");

        // initialize c with the given lrtConfig address
        c.initialize(admin);

        // The test contract is msg.sender for every call on c.
        // Since initialize sets lrtConfig = admin and the test contract is not
        // necessarily the admin, unpause may revert. Observe the outcome.
        bool unpaused;
        try c.unpause() {
            unpaused = true;
        } catch {
            unpaused = false;
        }

        // The test contract is msg.sender, not admin. The only way unpause can
        // succeed is if the admin role in the lrtConfig at `admin` is granted to
        // this test contract. We cannot know that from here without calling into
        // the config, so we encode the observable invariant: if unpause succeeded
        // then paused() must be false; if it reverted then paused() must still be
        // true (since initialize sets paused = false though... wait, initialize
        // calls __Pausable_init which sets paused = false).

        // Actually: initialize -> __Pausable_init() sets paused = false.
        // So initially paused() == false. unpause reverts if caller is not admin.
        // If unpause succeeds, paused() remains false. If it reverts, paused() is
        // still false. Thus the rule must involve admin.

        // Since the test contract is the caller, and it is the deployer of c but
        // NOT the admin of lrtConfig (unless admin == address(this)), we can
        // condition on whether admin equals address(this).
        if (admin == address(this)) {
            // In this case lrtConfig is this test contract, which does not
            // implement hasRole, so the call will likely revert. We cannot
            // rely on that. Instead, assert a general property that holds
            // regardless: if unpause did not revert, then paused() is false.
            assert(!unpaused || c.paused() == false);
        } else {
            // If admin is some other address, the test contract is not the admin
            // unless it was explicitly granted the role, which is impossible to
            // set up in a single transaction without calling grantRole on the
            // config. So unpause should revert. However, we must assert a
            // general rule that the checker can prove for ALL inputs. The rule
            //: unpause reverts or paused() is false.
            assert(!unpaused || c.paused() == false);
        }
    }

    receive() external payable {}
}

