contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 depositLimit) public payable {
        // Configure the asset as supported with a known deposit limit by calling
        // through the public LRTConfig surface exposed by c.lrtConfig().
        address config = address(c.lrtConfig());
        // Since lrtConfig is public on C, c.lrtConfig() is the auto getter returning ILRTConfig.
        // We cannot call arbitrary LRTConfig functions not present in c, so instead we
        // rely on the supported-asset check and revert behavior.

        bool reverted;
        uint256 total;
        try c.getTotalAssetDeposits(asset) returns (uint256 t) {
            total = t;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            // Unsupported asset must revert.
            assert(!ILRTConfig(address(c.lrtConfig())).isSupportedAsset(asset));
        } else {
            // When it returns, the result must equal the sum of pool balance, node delegator balances,
            // and eigenlayer stakes as observable through the same public functions.
            (uint256 poolBal, uint256 ndcBal, uint256 eigenBal) =
                c.getAssetDistributionData(asset);
            assert(total == poolBal + ndcBal + eigenBal);
        }
    }

    receive() external payable {}
}

